 for(position,x)in snapshot.index.entries.iter().enumerate(){let parent=out.insert_float("vdi3805_index_entry",&[Cell::Integer(1),ordinal(position)?,Cell::Text(&x.product_id),Cell::Integer(i64::from(x.sheet.0)),x.dn.map(|value|Cell::Integer(i64::from(value))).unwrap_or(Cell::Null)],&[])?;strings(out,"vdi3805_index_tag",parent,&x.tags)?;}
 for(key,g)in &snapshot.geometry{let b=g.bbox;let parent=out.insert_float("vdi3805_geometry",&[Cell::Integer(1),Cell::Text(key),Cell::Text(&g.id),Cell::Real(b.min_x),Cell::Real(b.min_y),Cell::Real(b.min_z),Cell::Real(b.max_x),Cell::Real(b.max_y),Cell::Real(b.max_z)],GEOMETRY)?;for(position,c)in g.connections.iter().enumerate(){out.insert_float("vdi3805_connection",&[Cell::Integer(parent),ordinal(position)?,Cell::Text(&c.id),Cell::Text(&c.medium),Cell::Real(c.position[0]),Cell::Real(c.position[1]),Cell::Real(c.position[2]),Cell::Real(c.direction[0]),Cell::Real(c.direction[1]),Cell::Real(c.direction[2]),Cell::Integer(i64::from(c.diameter_mm.is_some())),Cell::Real(c.diameter_mm.unwrap_or(0.0))],CONNECTION)?;}for(key,value)in &g.parameters{out.insert_float("vdi3805_geometry_parameter",&[Cell::Integer(parent),Cell::Text(key),Cell::Real(*value)],PARAMETER)?;}}
 for(key,c)in &snapshot.curves{let parent=out.insert_float("vdi3805_curve",&[Cell::Integer(1),Cell::Text(key),Cell::Text(&c.id)],&[])?;for(axis,u)in [(0,&c.x_unit),(1,&c.y_unit)]{out.insert_float("vdi3805_curve_unit",&[Cell::Integer(parent),Cell::Integer(axis),Cell::Text(&u.symbol),Cell::Text(quantity(u.kind)),Cell::Integer(i64::from(u.delta)),Cell::Real(u.si_factor)],UNIT)?;}for(position,p)in c.points.iter().enumerate(){out.insert_float("vdi3805_curve_point",&[Cell::Integer(parent),ordinal(position)?,Cell::Real(p.x),Cell::Real(p.y)],POINT)?;}}
