 let documents=entities(database,"vdi3805_document",4,&[],control)?;let catalogues=entities(database,"vdi3805_catalogue",2,&[],control)?;let files=entities(database,"vdi3805_file",7,&[],control)?;let bsns=entities(database,"vdi3805_building_system",5,&[],control)?;let limits=entities(database,"vdi3805_limits",6,&[],control)?;if documents.len()!=1||!documents.contains_key(&1){return Err(invalid("VDI3805 requires one document"));}mandatory(&catalogues,&documents)?;mandatory(&files,&catalogues)?;mandatory(&bsns,&files)?;mandatory(&limits,&documents)?;
 let ce=entities(database,"vdi3805_catalogue_extension",4,&[],control)?;let fe=entities(database,"vdi3805_file_extension",4,&[],control)?;let pe=entities(database,"vdi3805_product_extension",4,&[],control)?;let re=entities(database,"vdi3805_record_extension",4,&[],control)?;let products=entities(database,"vdi3805_product",8,&[],control)?;let titles=entities(database,"vdi3805_title",5,&[],control)?;let records=entities(database,"vdi3805_record",4,&[],control)?;let fields=entities(database,"vdi3805_record_field",4,&[],control)?;let configurations=entities(database,"vdi3805_configuration",5,&[],control)?;let refs=entities(database,"vdi3805_function_ref",4,&[],control)?;let valves=entities(database,"vdi3805_valve",8,VALVE,control)?;let radiators=entities(database,"vdi3805_radiator",8,RADIATOR,control)?;let pumps=entities(database,"vdi3805_pump",9,PUMP,control)?;let generators=entities(database,"vdi3805_heat_generator",6,HEAT,control)?;let generics=entities(database,"vdi3805_generic",2,&[],control)?;let generic_entries=entities(database,"vdi3805_generic_entry",6,&[],control)?;let accessories=entities(database,"vdi3805_accessory",6,&[],control)?;let components=entities(database,"vdi3805_component",5,&[],control)?;let editions=entities(database,"vdi3805_edition",4,&[],control)?;let index_entries=entities(database,"vdi3805_index_entry",6,&[],control)?;let tags=entities(database,"vdi3805_index_tag",4,&[],control)?;let geometries=entities(database,"vdi3805_geometry",10,GEOMETRY,control)?;let connections=entities(database,"vdi3805_connection",13,CONNECTION,control)?;let parameters=entities(database,"vdi3805_geometry_parameter",4,PARAMETER,control)?;let curves=entities(database,"vdi3805_curve",4,&[],control)?;let units=entities(database,"vdi3805_curve_unit",7,UNIT,control)?;let points=entities(database,"vdi3805_curve_point",5,POINT,control)?;mandatory(&configurations,&products)?;
